mkdir -p "$LIB_DIR" "$BIN_DIR" "$HW_DIR" "$VER_DIR" "$ZK_DIR" "$QUANTUM_DIR" "$ASTRO_DIR"
echo "--- Phase 1: Core Diffusive Memristor Spiking Neurons ---"
zig build-lib -O ReleaseFast -fPIC -dynamic --name dmsnn_core -lc -lm "$SRC_DIR/core/dmsnn.zig" -o "$LIB_DIR/libdmsnn_core.so"
