chpl "$SRC_DIR/distributed/quantum_hybrid.chpl" --fast -o "$BIN_DIR/quantum_hybrid_exec"
ponyc "$SRC_DIR/actors/quantum_actor.pony" -o "$BIN_DIR/quantum_actor"
echo "--- Phase 6: Hardware Synthesis for Memristor Array ---"
clash --verilog "$SRC_DIR/hw/diffusive_memristor.hs" -o "$HW_DIR/memristor_neuron.v"
