nextpnr-ice40 --hx8k --json "$HW_DIR/photonic_synth.json" --pcf "$SRC_DIR/hw/pins.pcf" --asc "$HW_DIR/photonic.asc"
icepack "$HW_DIR/photonic.asc" "$HW_DIR/photonic.bin"
