lean "$SRC_DIR/verification/dmsnn_stability.lean" --output-dir="$VER_DIR"
agda "$SRC_DIR/verification/spiking_invariants.agda" --output-dir="$VER_DIR"
isabelle build -D "$SRC_DIR/verification/isabelle" -d "$VER_DIR/isabelle"
viper "$SRC_DIR/verification/memristor_bounds.vpr" --enable-verifier
