gcc -o "$VER_DIR/pan" pan.c
"$VER_DIR/pan" -a "$VER_DIR/spin.out"
echo "--- Phase 9: ZK Proofs for Quantum Embeddings ---"
circom "$SRC_DIR/zk/quantum_astrology.circom" --r1cs --wasm --sym -o "$ZK_DIR"
