curl -H "X-IBM-Quantum-Token: crnv1bluemixpublicquantum-computingus-easta3739b57074604d31a8042e8955ee8cc3646a80b5-12f7-44e8-b8a0-d8c810073bd21"  > "$QUANTUM_DIR/qpu_status.json"
