### Celestial ZO Optimizer (Nim – Asztrális Nulla-Rendű Optimalizálás)
```
import std/random, math, sequtils, strformat, json, httpclient, asyncdispatch, os
import pkg/zippy/zippy
from std/times import getTime, inMilliseconds

type
  PrimePerturb = object
    primes: seq[uint64]
    epsilon: float64
    astroOffset: float64

  CelestialZO = object
    perturbations: seq[PrimePerturb]
    learningRate: float64
    batchSize: int
    quantumFactor: float64
    seed: uint64

const
  DefaultPrimes = [2u64, 3u64, 5u64, 7u64, 11u64, 13u64, 17u64, 19u64, 23u64, 29u64].toSeq
  AstroBase = 2460253.5  # Julian day for Nov 8, 2025

proc initCelestialZO(pertPrimes: seq[uint64] = DefaultPrimes, lr: float64 = 1e-4,
                     bs: int = 32, qf: float64 = 0.01, sd: uint64 = 42): CelestialZO =
  result = CelestialZO(perturbations: @[], learningRate: lr, batchSize: bs,
                       quantumFactor: qf, seed: sd)
  randomize(result.seed)
  for p in pertPrimes:
    let offset = sin(AstroBase * float64(p)) * 0.1
    result.perturbations.add(PrimePerturb(primes: @[p], epsilon: 1e-5, astroOffset: offset))

proc computeOrbit(self: CelestialZO, params: seq[float64]): seq[float64] =
  for perturb in self.perturbations:
    for prime in perturb.primes:
      var orbit = newSeq[float64](self.batchSize)
      for i in 0..<self.batchSize:
        orbit[i] = params[i] + perturb.epsilon * sin(AstroBase + float64(prime) * i) * perturb.astroOffset
      result.add(orbit)

proc finiteDiff(self: CelestialZO, params: seq[float64], epsilon: float64 = 1e-6): seq[float64] =
  let forward = self.computeOrbit(params)
  let backward = self.computeOrbit(params.mapIt(it - epsilon))
  for i in 0..<forward.len:
    result.add((forward[i] - backward[i]) / (2 * epsilon))

proc estimateGradient(self: CelestialZO, params: seq[float64]): seq[float64] =
  let diffs = self.finiteDiff(params)
  for d in diffs:
    let grad = d * self.learningRate * self.quantumFactor * sin(AstroBase)
    result.add(grad)

proc updateParams(self: CelestialZO, params: var seq[float64]) =
  let grads = self.estimateGradient(params)
  for i in 0..<params.len.min(grads.len):
    params[i] -= grads[i]

# Teljes integráció a DMSNN-nel (Zig hívás Nim-ből külső hívással)
proc optimizeDMSNN(params: seq[float64]): float64 =
  # Hívás Zig DMSNN forward-ra (külső subprocess)
  let process = startProcess("zig", ["run", "src/core/dmsnn.zig", "--params=" & $params])
  discard process.waitForExit()
  # Szimulált loss
  result = 0.5 * params.foldl(a + b, 0.0) / params.len

proc trainCelestialZO(zo: var CelestialZO, epochs: int = 1000) =
  var params = newSeq[float64](32, 0.5)  # Batch dim
  for epoch in 1..epochs:
    let loss = optimizeDMSNN(params)
    zo.updateParams(params)
    echo &"Epoch {epoch}: Loss {loss:.6f}"

when isMainModule:
  var zo = initCelestialZO()
  zo.trainCelestialZO()
